function saveDataImage(?string $data, string $folder): ?string {
    if (!$data || !str_starts_with($data, 'data:image/')) return null;
    if (!preg_match('#^data:image/(png|jpeg|jpg|webp);base64,(.+)$#', $data, $m)) fail('Fotoğraf formatı desteklenmiyor.');
    $raw = base64_decode($m[2], true);
    if ($raw === false || strlen($raw) > 5 * 1024 * 1024) fail('Fotoğraf en fazla 5 MB olabilir.');
    $ext = $m[1] === 'jpeg' ? 'jpg' : $m[1];
    $dir = dirname(__DIR__) . '/uploads/' . $folder;
    if (!is_dir($dir)) mkdir($dir, 0775, true);
    $name = bin2hex(random_bytes(12)) . '.' . $ext;
    file_put_contents($dir . '/' . $name, $raw);
    return '../uploads/' . $folder . '/' . $name;
}
function syncSessionUser(PDO $pdo, int $id): void {
    $q=$pdo->prepare('SELECT id,username,email,role,city,status FROM users WHERE id=?');$q->execute([$id]);$u=$q->fetch();
    if($u && $u['status']==='active'){unset($u['status']);$_SESSION['user']=$u;}
}


function recountReports(PDO $pdo, int $target): int {
    $q=$pdo->prepare('SELECT COUNT(*) FROM reports WHERE target_type="user" AND target_id=? AND status IN ("open","reviewing")');$q->execute([$target]);$count=(int)$q->fetchColumn();$pdo->prepare('UPDATE users SET report_count=? WHERE id=?')->execute([$count,$target]);if($count<10){$pdo->prepare('UPDATE users SET status="active" WHERE id=? AND status="suspended" AND role<>"admin"')->execute([$target]);}return $count;
}

