case 'vote_offer': $u=requireUser();$oid=(int)$in['offer_id'];$q=$pdo->prepare('SELECT cart_id FROM seller_offers WHERE id=?');$q->execute([$oid]);$cid=(int)$q->fetchColumn();$pdo->prepare('INSERT INTO cart_votes(cart_id,offer_id,user_id,vote) VALUES(?,?,?,1) ON DUPLICATE KEY UPDATE offer_id=VALUES(offer_id)')->execute([$cid,$oid,$u['id']]);ok(null,'Oyunuz kaydedildi.');
case 'create_offer':
    $u=requireRole(['seller','admin']);$q=$pdo->prepare('SELECT id FROM sellers WHERE user_id=? AND verification_status="verified"');$q->execute([$u['id']]);$sid=(int)$q->fetchColumn();if(!$sid)fail('Doğrulanmış satıcı olmalısınız.');$q=$pdo->prepare('INSERT INTO seller_offers(cart_id,seller_id,unit_price,minimum_quantity,maximum_quantity,shipping_cost,delivery_days,warranty_type,gift_info,expires_at,status) VALUES(?,?,?,?,?,?,?,?,?,DATE_ADD(NOW(),INTERVAL 7 DAY),"active")');$q->execute([(int)$in['cart_id'],$sid,(float)$in['unit_price'],max(1,(int)$in['minimum_quantity']),max(1,(int)$in['maximum_quantity']),(float)($in['shipping_cost']??0),max(1,(int)($in['delivery_days']??3)),clean((string)($in['warranty_type']??'')),clean((string)($in['gift_info']??''))]);ok(null,'Teklif yayınlandı.');
case 'admin_dashboard':
    requireRole(['admin']);$stats=$pdo->query('SELECT (SELECT COUNT(*) FROM users) users,(SELECT COUNT(*) FROM users WHERE status="suspended") suspended,(SELECT COUNT(*) FROM sellers WHERE verification_status="pending") pending_sellers,(SELECT COUNT(*) FROM reports WHERE status="open") open_reports')->fetch();$sellers=$pdo->query('SELECT s.*,u.username,u.email FROM sellers s JOIN users u ON u.id=s.user_id ORDER BY s.created_at DESC')->fetchAll();$reports=$pdo->query('SELECT r.*,a.username reporter_name,t.username target_name,t.status target_status FROM reports r JOIN users a ON a.id=r.reporter_id LEFT JOIN users t ON t.id=r.target_id AND r.target_type="user" ORDER BY r.created_at DESC LIMIT 100')->fetchAll();ok(['stats'=>$stats,'sellers'=>$sellers,'reports'=>$reports]);
case 'admin_verify_seller': requireRole(['admin']);$pdo->prepare('UPDATE sellers SET verification_status=? WHERE id=?')->execute([in_array(($in['status']??''),['verified','rejected'],true)?$in['status']:'verified',(int)$in['seller_id']]);$q=$pdo->prepare('SELECT user_id FROM sellers WHERE id=?');$q->execute([(int)$in['seller_id']]);$uid=(int)$q->fetchColumn();$pdo->prepare('UPDATE users SET role="seller" WHERE id=?')->execute([$uid]);ok(null,'Satıcı durumu güncellendi.');
case 'admin_user_status': requireRole(['admin']);$pdo->prepare('UPDATE users SET status=? WHERE id=? AND role<>"admin"')->execute([in_array(($in['status']??''),['active','suspended'],true)?$in['status']:'active',(int)$in['user_id']]);ok(null,'Kullanıcı durumu güncellendi.');
default: fail('API işlemi bulunamadı.',404);
}
} catch(Throwable $e){fail(envv('APP_DEBUG','false')==='true'?$e->getMessage():'Beklenmeyen bir hata oluştu.',500);}
